declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach(['site_title','welcome_text','privacy_text'] as $k)$s->execute([$k,trim((string)($_POST[$k]??''))]);audit('update_settings');flash('success','บันทึกการตั้งค่าแล้ว');redirect('admin/settings.php');}page_header('ตั้งค่า',true);require __DIR__.'/_nav.php';?><h1>ตั้งค่าเว็บไซต์</h1><div class="form-card"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>ชื่อระบบ</label><input name="site_title" value="<?=e(setting('site_title',APP_NAME))?>"></div><div class="field"><label>ข้อความต้อนรับ</label><textarea name="welcome_text" rows="3"><?=e(setting('welcome_text'))?></textarea></div><div class="field"><label>ข้อความความเป็นส่วนตัว</label><textarea name="privacy_text" rows="4"><?=e(setting('privacy_text'))?></textarea></div><button class="btn">บันทึก</button></form></div><?php page_footer();?>
